import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeFieldType;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneProperties;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateTimeFormatter_parseInto_TriageGen1Test {

    /**
     * Test that passing a null instant throws IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendYear().toFormatter();
        formatter.parseInto(null, "2023", 0);
    }

    /**
     * Test successful parsing of a simple date pattern.
     * Covers the basic execution path.
     */
    @Test
    public void testParseInto_BasicSuccess() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendYear().appendMonth(DateTimeParser.STRICT).appendDayOfMonth(DateTimeParser.STRICT).toFormatter();
        // Using MutableDateTime as it implements ReadWritableInstant
        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0);
        String text = "2023-05-15";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        Assert.assertEquals(10, newPos);
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(5, instant.getMonthOfYear());
        Assert.assertEquals(15, instant.getDayOfMonth());
    }

    /**
     * Test parsing with offset enabled (iOffsetParsed = true).
     * Covers the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
     */
    @Test
    public void testParseInto_WithOffsetParsed() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendMonth(DateTimeParser.STRICT)
                .appendDayOfMonth(DateTimeParser.STRICT)
                .appendLiteral('+')
                .appendOffset("+HH:mm")
                .withOffsetParsed()
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0);
        String text = "2023-05-15+05:00";

        formatter.parseInto(instant, text, 0);

        // The zone should be updated to +05:00
        Assert.assertEquals("+05:00", instant.getZone().getID());
    }

    /**
     * Test parsing where offset is not explicitly requested but is present in the bucket.
     * Covers the branch: else if (bucket.getZone() != null)
     */
    @Test
    public void testParseInto_WithZoneInBucket() {
        // We use a pattern that includes zone information but we don't call withOffsetParsed()
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendMonth(DateTimeParser.STRICT)
                .appendDayOfMonth(DateTimeParser.STRICT)
                .appendLiteral(' ')
                .appendZone(DateTimeParser.STRICT)
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0);
        String text = "2023-05-15 UTC";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals("UTC", instant.getZone().getID());
    }

    /**
     * Test the branch where iZone is not null.
     * Covers the branch: if (iZone != null) { instant.setZone(iZone); }
     */
    @Test
    public void testParseInto_WithFixedZone() {
        DateTimeZone fixedZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendMonth(DateTimeParser.STRICT)
                .appendDayOfMonth(DateTimeParser.STRICT)
                .toFormatter()
                .withZone(fixedZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0);
        String text = "2023-05-15";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals("America/New_York", instant.getZone().getID());
    }

    /**
     * Test parsing with specific Locale and Pivot Year influences.
     * This ensures the parser configuration is passed correctly to the bucket.
     */
    @Test
    public void testParseInto_WithLocaleAndPivotYear() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendMonthLenient()
                .appendDayOfMonth()
                .toFormatter()
                .withLocale(Locale.FRENCH)
                .withPivotYear(2000);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2000, 1, 1, 0, 0);
        // Testing a 2-digit year with pivot year logic
        String text = "23-05-15"; 

        int newPos = formatter.parseInto(instant, text, 0);

        Assert.assertTrue(newPos > 0);
        Assert.assertEquals(2023, instant.getYear());
    }
}
